export const LAZY_TAB_RENDER = true

const DIFF_TAG_LABELS = Object.freeze({
  added: '新增',
  modified: '变更',
  removed: '拟移除',
  impacted: '波及',
})

function findGraphCycles(nodeIds, edges) {
  const adj = new Map(nodeIds.map((id) => [id, []]))
  for (const e of edges) {
    if (adj.has(e.fromId) && adj.has(e.toId) && e.fromId !== e.toId) {
      adj.get(e.fromId).push(e.toId)
    }
  }
  let idx = 0
  const indices = new Map(), low = new Map(), onStack = new Set(), stack = [], cycles = []
  const strongConnect = (v) => {
    indices.set(v, idx); low.set(v, idx); idx += 1
    stack.push(v); onStack.add(v)
    for (const w of adj.get(v) || []) {
      if (!indices.has(w)) {
        strongConnect(w)
        low.set(v, Math.min(low.get(v), low.get(w)))
      } else if (onStack.has(w)) {
        low.set(v, Math.min(low.get(v), indices.get(w)))
      }
    }
    if (low.get(v) === indices.get(v)) {
      const comp = []
      while (stack.length > 0) {
        const w = stack.pop()
        onStack.delete(w)
        comp.push(w)
        if (w === v) break
      }
      if (comp.length > 1) cycles.push(comp.sort())
    }
  }
  for (const id of nodeIds) if (!indices.has(id)) strongConnect(id)
  return cycles
}

/** 聚合耦合度（fanIn / fanOut / inCycle / cycleMembers / churnCommits），兼顾静态分析与功能地图降级。 */
export function computeNodeCouplingMap(treeNodes = [], treeEdges = [], analysis = null) {
  const nodeIds = treeNodes.map((n) => n.id)
  const inMap = new Map(nodeIds.map((id) => [id, 0]))
  const outMap = new Map(nodeIds.map((id) => [id, 0]))
  for (const e of treeEdges) {
    if (outMap.has(e.fromId)) outMap.set(e.fromId, outMap.get(e.fromId) + 1)
    if (inMap.has(e.toId)) inMap.set(e.toId, inMap.get(e.toId) + 1)
  }
  const graphCycles = findGraphCycles(nodeIds, treeEdges)
  const cycleByNode = new Map()
  for (const comp of graphCycles) {
    for (const id of comp) cycleByNode.set(id, comp)
  }

  const fileNodeMap = new Map()
  if (Array.isArray(analysis?.nodes)) {
    for (const fn of analysis.nodes) fileNodeMap.set(fn.id, fn)
  }
  const fileCyclesByFile = new Map()
  if (Array.isArray(analysis?.cycles)) {
    for (const cyc of analysis.cycles) {
      const members = Array.isArray(cyc?.nodes) ? cyc.nodes : []
      for (const f of members) fileCyclesByFile.set(f, members)
    }
  }

  const out = new Map()
  for (const n of treeNodes) {
    const owned = [...new Set([...(n.entrypoints || []), ...(n.modules || [])])]
    let churnCommits = 0
    let fileInCycle = false
    const fileCycleMembers = new Set()
    for (const rel of owned) {
      const fn = fileNodeMap.get(rel)
      if (fn) {
        churnCommits += Number(fn.churnCommits) || 0
        if (fn.inCycle) fileInCycle = true
      }
      const fc = fileCyclesByFile.get(rel)
      if (fc) {
        fileInCycle = true
        for (const m of fc) fileCycleMembers.add(m)
      }
    }
    const graphMembers = cycleByNode.get(n.id) || []
    const inCycle = graphMembers.length > 0 || fileInCycle
    const cycleMembers = graphMembers.length > 0 ? graphMembers : [...fileCycleMembers].slice(0, 6)
    out.set(n.id, {
      fanIn: inMap.get(n.id) || 0,
      fanOut: outMap.get(n.id) || 0,
      inCycle,
      cycleMembers,
      churnCommits,
    })
  }
  return out
}

export function buildSharedSvgDefsHtml(hasActiveDiff = true) {
  const mk = (id, cls) => `<marker id="${id}" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 1 2 L 8 5 L 1 8 z" class="${cls}"/></marker>`
  const sh = '<filter id="pf-card-shadow" x="-8%" y="-8%" width="116%" height="126%"><feDropShadow dx="0" dy="1.5" stdDeviation="2.2" flood-color="#0F172A" flood-opacity="0.12"/></filter>'
  const tri = '<marker id="pf-arr-tri" viewBox="0 0 12 12" refX="10" refY="6" markerWidth="8" markerHeight="8" orient="auto"><path d="M1 2L10 6L1 10z" fill="var(--pf-svg-node-fill)" stroke="var(--eg)" stroke-width="1.3"/></marker>'
  const dia = '<marker id="pf-arr-dia" viewBox="0 0 12 12" refX="10" refY="6" markerWidth="8" markerHeight="8" orient="auto"><path d="M1 6L6 2L11 6L6 10z" fill="var(--pf-svg-node-fill)" stroke="var(--eg)" stroke-width="1.3"/></marker>'
  const diffMks = hasActiveDiff
    ? mk('pf-arr-added', 'svg-arrow-added') + mk('pf-arr-modified', 'svg-arrow-modified') + mk('pf-arr-removed', 'svg-arrow-removed') + mk('pf-arr-impacted', 'svg-arrow-impacted')
    : ''
  return `<svg id="pf-svg-defs" width="0" height="0" style="position:absolute" aria-hidden="true"><defs>${sh}${mk('pf-arr-muted', 'svg-arrow-muted')}${mk('pf-arr-accent', 'svg-arrow-accent')}${mk('pf-arr-route', 'svg-arrow-route')}${diffMks}${tri}${dia}</defs></svg>`
}

function formatNodeMetaLine(node, coupling) {
  const st = node.diffState || 'context'
  const d = node.changeDetail || {}
  if ((st === 'added' || st === 'modified' || st === 'removed') && d.before && d.after) {
    return truncateLabel(`${d.before} -> ${d.after}`, 34)
  }
  const modCnt = (node.modules || []).length
  return `${modCnt} 文件 · 入 ${coupling.fanIn} / 出 ${coupling.fanOut}${coupling.inCycle ? ' · 含环' : ''}`
}

/** 服务端渲染首屏纯矢量 `<svg id="svg-architecture">`（无左侧彩条、零 CSS scale()、零 will-change、单层背景）。 */
export function renderArchitectureSvg(tree, { couplingMap = new Map() } = {}) {
  const w = Math.max(640, Math.round(Number(tree?.width) || 960))
  const h = Math.max(400, Math.round(Number(tree?.height) || 540))
  const padX = 24
  const padTop = 76
  const padBottom = 84
  const vb = `${-padX} ${-padTop} ${w + padX * 2} ${h + padTop + padBottom}`
  const parts = [
    `<svg id="svg-architecture" class="pf-studio-svg" viewBox="${vb}" data-base-vb="${vb}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="架构全景图">`,
  ]

  // Domain zones (L1 surface + header strip + clean hairline border)
  const domains = Array.isArray(tree?.domains) ? tree.domains : []
  domains.forEach((z, idx) => {
    const code = String(idx + 1).padStart(2, '0')
    const headD = `M ${z.x} ${z.y + 12} Q ${z.x} ${z.y} ${z.x + 12} ${z.y} L ${z.x + z.w - 12} ${z.y} Q ${z.x + z.w} ${z.y} ${z.x + z.w} ${z.y + 12} L ${z.x + z.w} ${z.y + 36} L ${z.x} ${z.y + 36} Z`
    parts.push(
      `<g class="svg-zone" data-domain-id="${escapeXml(z.id)}">`
      + `<rect x="${z.x}" y="${z.y}" width="${z.w}" height="${z.h}" rx="12" class="svg-zone-box"/>`
      + `<path d="${headD}" class="svg-zone-head"/>`
      + `<text x="${z.x + 14}" y="${z.y + 24}" class="svg-zone-code">${code}</text>`
      + `<text x="${z.x + 38}" y="${z.y + 24}" class="svg-zone-title">${escapeXml(z.shortTitle || z.title || z.id)}</text>`
      + `<text x="${z.x + z.w - 14}" y="${z.y + 24}" text-anchor="end" class="svg-zone-meta">${Number(z.featureCount) || 0} 模块</text>`
      + `<line x1="${z.x}" y1="${z.y + 36}" x2="${z.x + z.w}" y2="${z.y + 36}" class="svg-zone-divider"/>`
      + '</g>',
    )
  })

  // Edges layer
  const edges = Array.isArray(tree?.edges) ? tree.edges : []
  const edgeSvg = edges.map((e) => {
    const st = e.edgeState && e.edgeState !== 'context' ? e.edgeState : 'context'
    const cls = st !== 'context' ? `svg-edge pf-edge-${escapeXml(st)}` : 'svg-edge'
    const mk = st !== 'context' ? `url(#pf-arr-${escapeXml(st)})` : 'url(#pf-arr-muted)'
    return `<path class="${cls}" data-from-id="${escapeXml(e.fromId)}" data-to-id="${escapeXml(e.toId)}" d="${escapeXml(roundPathD(e.pathD))}" marker-end="${mk}"/>`
  }).join('')
  parts.push(`<g class="svg-edges-layer">${edgeSvg}</g>`)

  // Nodes layer (clean full-edge hairline borders + subtle status dot/label only — ZERO left color bars!)
  const nodes = Array.isArray(tree?.nodes) ? tree.nodes : []
  const nodeSvg = nodes.map((n) => {
    const st = n.diffState || 'context'
    const hasDiff = st !== 'context'
    const cpl = couplingMap.get(n.id) || { fanIn: 0, fanOut: 0, inCycle: false }
    const cls = hasDiff ? `svg-node pf-diff-${escapeXml(st)}` : 'svg-node'
    const idDisp = truncateLabel(n.id, hasDiff ? 22 : 30)
    const titleDisp = truncateLabel(n.shortTitle || n.title || n.id, 28)
    const metaDisp = formatNodeMetaLine(n, cpl)
    const badgeSvg = hasDiff && DIFF_TAG_LABELS[st]
      ? `<circle cx="${n.x + n.w - 44}" cy="${n.y + 18}" r="3.5" class="svg-diff-dot-${escapeXml(st)}"/><text x="${n.x + n.w - 12}" y="${n.y + 22}" text-anchor="end" class="svg-diff-tag svg-diff-${escapeXml(st)}">${escapeXml(DIFF_TAG_LABELS[st])}</text>`
      : ''
    const titleCls = st === 'removed' ? 'svg-node-title is-removed' : 'svg-node-title'
    return `<g class="${cls}" data-node-id="${escapeXml(n.id)}" data-domain="${escapeXml(n.domain || '')}" tabindex="0" role="button" aria-label="${escapeXml(n.title || n.id)}">`
      + `<rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="10" class="svg-node-box"/>`
      + `<text x="${n.x + 14}" y="${n.y + 22}" class="svg-node-id">${escapeXml(idDisp)}</text>`
      + badgeSvg
      + `<text x="${n.x + 14}" y="${n.y + 52}" class="${titleCls}">${escapeXml(titleDisp)}</text>`
      + `<text x="${n.x + 14}" y="${n.y + 84}" class="svg-node-meta">${escapeXml(metaDisp)}</text>`
      + '</g>'
  }).join('')
  parts.push(`<g class="svg-nodes-layer">${nodeSvg}</g></svg>`)
  return parts.join('')
}

const rInt = (v) => Math.round(Number(v) || 0)
const roundPathD = (d) => String(d || '').replace(/\d+\.\d+/g, (m) => String(Math.round(Number(m)))).replace(/\s*([MLQ])\s*/g, '$1').replace(/\s+/g, ' ').trim()

function rebuildPrunedTreeRoot(rawNodes, repoName = '') {
  const dirsOnly = rawNodes.filter((n) => (Number(n.depth) || 0) <= 2 && !n.isFile).slice(0, 48)
  const kept = dirsOnly.length >= 2 ? dirsOnly : rawNodes.slice(0, 48)
  const byId = new Map()
  for (const n of kept) {
    byId.set(n.id, {
      name: (n.depth === 0 && repoName) ? repoName : (n.label || n.shortLabel || n.id),
      path: n.path || '',
      isFile: Boolean(n.isFile),
      fileCount: Number(n.fileCount) || 0,
      children: [],
    })
  }
  let root = null
  for (const n of kept) {
    const cur = byId.get(n.id)
    if (!n.parentId || !byId.has(n.parentId)) {
      if (!root) root = cur
    } else {
      byId.get(n.parentId).children.push(cur)
    }
  }
  return root || byId.values().next().value || null
}

function compactDiagramData(kind, d, { repoName = '' } = {}) {
  if (!d || typeof d !== 'object') return null
  const base = { w: rInt(d.width) || 640, h: rInt(d.height) || 360 }
  if (kind === 'workflow') {
    return {
      ...base,
      stages: (d.stages || []).map((s) => ({ t: s.title, x: rInt(s.x), y: rInt(s.y), w: rInt(s.w) })),
      lanes: (d.lanes || []).map((l) => ({ id: l.id, t: l.shortTitle || l.title, x: rInt(l.x), y: rInt(l.y), w: rInt(l.w), h: rInt(l.h), lw: rInt(l.labelW) })),
      nodes: (d.nodes || []).map((n) => ({ id: n.id, t: n.shortTitle || n.title, s: truncateLabel(n.shortSummary || '', 18), x: rInt(n.x), y: rInt(n.y), w: rInt(n.w), h: rInt(n.h), ds: n.diffState || 'context' })),
      edges: (d.edges || []).map((e) => ({ f: e.fromId, t: e.toId, d: roundPathD(e.pathD), es: e.edgeState || 'context' })),
    }
  }
  if (kind === 'tree') {
    const rawNodes = Array.isArray(d.nodes) ? d.nodes : []
    const src = rawNodes.length > 48
      ? layoutTreeDiagram({ root: rebuildPrunedTreeRoot(rawNodes, repoName) })
      : d
    return {
      w: rInt(src.width) || base.w,
      h: rInt(src.height) || base.h,
      nodes: (src.nodes || []).map((n, idx) => {
        const t = (idx === 0 && n.depth === 0 && repoName) ? repoName : (n.shortLabel || n.label)
        return {
          id: n.id, t,
          ...(n.parentId ? { p: n.parentId } : {}),
          ...(n.path && n.path !== n.id ? { fp: n.path } : {}),
          ...(n.fileCount ? { fc: n.fileCount } : {}),
          ...(n.isFile ? { lf: 1 } : {}),
          x: rInt(n.x), y: rInt(n.y), w: rInt(n.w), h: rInt(n.h),
        }
      }),
      edges: (src.edges || []).map((e) => ({ f: e.fromId, t: e.toId, d: roundPathD(e.pathD) })),
    }
  }
  if (kind === 'erd') {
    return {
      ...base,
      nodes: (d.nodes || []).map((n) => ({
        id: n.id, t: n.shortLabel || n.label,
        ...(n.source ? { src: n.source } : {}),
        flds: (n.visibleFields || n.fields || []).slice(0, 12),
        ...(Array.isArray(n.fields) && n.fields.length > 12 ? { aflds: n.fields } : {}),
        ...(n.extraFieldCount ? { ex: n.extraFieldCount } : {}),
        x: rInt(n.x), y: rInt(n.y), w: rInt(n.w), h: rInt(n.h),
      })),
      edges: (d.edges || []).map((e) => ({ f: e.fromId, t: e.toId, d: roundPathD(e.pathD), ...(e.label ? { l: e.label } : {}), ...(e.cardinality ? { c: e.cardinality } : {}), lx: rInt(e.labelX), ly: rInt(e.labelY) })),
    }
  }
  if (kind === 'class') {
    return {
      ...base,
      nodes: (d.nodes || []).map((n) => ({ id: n.id, t: n.shortLabel || n.label, x: rInt(n.x), y: rInt(n.y), w: rInt(n.w), h: rInt(n.h) })),
      edges: (d.edges || []).map((e) => ({ f: e.fromId, t: e.toId, ...(e.kind && e.kind !== 'extends' ? { k: e.kind } : {}), d: roundPathD(e.pathD), ...(e.lineStyle && e.lineStyle !== 'solid' ? { ls: e.lineStyle } : {}), ...(e.marker && e.marker !== 'hollow-triangle' ? { mk: e.marker } : {}) })),
    }
  }
  if (kind === 'sequence') {
    return {
      ...base,
      nodes: (d.nodes || []).map((n) => ({ id: n.id, t: n.shortLabel || n.label, ...(n.label && n.label !== (n.shortLabel || n.label) ? { fl: n.label } : {}), x: rInt(n.x), y: rInt(n.y), w: rInt(n.w), h: rInt(n.h) })),
      lifelines: (d.lifelines || []).map((ll) => ({ x: rInt(ll.x), y1: rInt(ll.y1), y2: rInt(ll.y2) })),
      messages: (d.messages || []).map((m) => ({ f: m.fromId, t: m.toId, ...(m.hop ? { hp: m.hop } : {}), d: roundPathD(m.pathD), l: m.label || '', lx: rInt(m.labelX), ly: rInt(m.labelY) })),
    }
  }
  if (kind === 'lifecycle') {
    return {
      ...base,
      nodes: (d.nodes || []).map((n) => ({ id: n.id, t: n.shortLabel || n.label, ...(n.onSpine ? { sp: 1 } : {}), x: rInt(n.x), y: rInt(n.y), w: rInt(n.w), h: rInt(n.h) })),
      edges: (d.edges || []).map((e) => ({ f: e.fromId, t: e.toId, d: roundPathD(e.pathD), ...(e.label ? { l: e.label } : {}), ...(e.isRollback ? { rb: 1 } : {}), lx: rInt(e.labelX), ly: rInt(e.labelY) })),
    }
  }
  if (kind === 'dataflow') {
    return {
      ...base,
      groups: (d.groups || []).map((g) => ({ t: g.title, x: rInt(g.x), y: rInt(g.y), w: rInt(g.w), h: rInt(g.h) })),
      nodes: (d.nodes || []).map((n) => ({ id: n.id, t: n.shortLabel || n.label, ...(n.source ? { src: n.source } : {}), ...(n.stageIndex ? { si: n.stageIndex } : {}), x: rInt(n.x), y: rInt(n.y), w: rInt(n.w), h: rInt(n.h) })),
      edges: (d.edges || []).map((e) => ({ f: e.fromId, t: e.toId, d: roundPathD(e.pathD) })),
    }
  }
  if (kind === 'timeline') {
    const rawNodes = Array.isArray(d.nodes) ? d.nodes : []
    const src = rawNodes.length > 24
      ? layoutTimelineDiagram({
        events: rawNodes.slice(-24).map((n) => ({ id: n.id, kind: n.kind || 'event', date: n.date || '', sha: n.sha || '', label: n.label || n.shortLabel || n.id })),
      })
      : d
    return {
      w: rInt(src.width) || base.w,
      h: rInt(src.height) || base.h,
      axis: src.axis ? { x1: rInt(src.axis.x1), x2: rInt(src.axis.x2), y: rInt(src.axis.y) } : null,
      breaks: (src.quietBreaks || []).map((b) => ({ x: rInt(b.x), y: rInt(b.y), l: b.label })),
      nodes: (src.nodes || []).map((n) => {
        const t = n.shortLabel || n.label
        return {
          id: n.id, t,
          ...(n.label && n.label !== t ? { fl: n.label } : {}),
          dt: String(n.date || '').slice(0, 10),
          ...(n.sha ? { sha: String(n.sha).slice(0, 10) } : {}),
          k: n.kind || 'event', x: rInt(n.x), y: rInt(n.y), w: rInt(n.w), h: rInt(n.h),
        }
      }),
      edges: (src.edges || []).map((e) => ({ f: e.fromId, t: e.toId, d: roundPathD(e.pathD) })),
    }
  }
  if (kind === 'waterfall') {
    return {
      ...base,
      totalMs: d.totalMs || 0,
      ticks: (d.ticks || []).map((t) => ({ l: t.label, x: rInt(t.x) })),
      nodes: (d.nodes || []).map((n) => {
        const t = n.shortLabel || n.label
        return { id: n.id, t, ...(n.label && n.label !== t ? { fl: n.label } : {}), st: n.startMs || 0, en: n.endMs || 0, lx: rInt(n.labelX), y: rInt(n.y), bx: rInt(n.barX), bw: rInt(n.barW), h: rInt(n.h), ms: n.durationMs }
      }),
    }
  }
  return null
}

/** 构造单源索引压缩 JSON（schemaVersion=3），完整兼容 `tree.nodes[].diffState`（[Sandbox-C8]）。 */
export function buildIndexedVisualPayload(model, {
  mode = 'architecture-map',
  couplingMap = new Map(),
  parentBriefHref = null,
  childBriefLinks = [],
  siblingBriefLinks = [],
} = {}) {
  const tree = model?.tree || { width: 680, height: 400, domains: [], nodes: [], edges: [] }
  const activeTabs = Array.isArray(model?.activeTabs)
    ? model.activeTabs.map((t) => ({ id: t.id, tier: Number(t.tier) || 1, title: t.title || t.id }))
    : [{ id: 'architecture', tier: 1, title: '架构全景' }, { id: 'workflow', tier: 1, title: '主流程' }]

  const diagrams = {}
  const srcDiagrams = model?.diagrams || {}
  for (const tab of activeTabs) {
    if (tab.id === 'architecture') continue
    const compacted = compactDiagramData(tab.id, srcDiagrams[tab.id], { repoName: model?.repoName || '' })
    if (compacted) diagrams[tab.id] = compacted
  }

  return {
    schemaVersion: 3,
    mode,
    title: model?.title || '架构全景图',
    repoName: model?.repoName || '项目仓库',
    hasActiveDiff: Boolean(model?.hasActiveDiff),
    defaultTab: mode === 'visual-brief' ? 'brief' : 'architecture',
    parentBriefHref: parentBriefHref || null,
    childBriefLinks: Array.isArray(childBriefLinks) ? childBriefLinks : [],
    ...(mode === 'visual-brief' && Array.isArray(siblingBriefLinks) && siblingBriefLinks.length > 0 ? { siblingBriefLinks } : {}),
    activeTabs,
    tree: {
      width: Math.round(Number(tree.width) || 680),
      height: Math.round(Number(tree.height) || 400),
      domains: (tree.domains || []).map((d) => (
        mode === 'architecture-map' && LAZY_TAB_RENDER
          ? { id: d.id, title: d.title }
          : { id: d.id, title: d.title, shortTitle: d.shortTitle || d.title, x: d.x, y: d.y, w: d.w, h: d.h, featureCount: d.featureCount || 0 }
      )),
      nodes: (tree.nodes || []).map((n) => {
        const cpl = couplingMap.get(n.id) || { fanIn: 0, fanOut: 0, inCycle: false, cycleMembers: [], churnCommits: 0 }
        const mods = Array.isArray(n.modules) ? n.modules : []
        const entries = Array.isArray(n.entrypoints) ? n.entrypoints : []
        const tests = Array.isArray(n.tests) ? n.tests : []
        const vtools = Array.isArray(n.verifyTools) ? n.verifyTools : []
        const anchors = Array.isArray(n.docAnchors) ? n.docAnchors : []
        const item = {
          id: n.id,
          title: n.title,
          domain: n.domain,
          diffState: n.diffState || 'context',
          risk: n.risk || 'medium',
          x: Math.round(n.x || 0), y: Math.round(n.y || 0), w: Math.round(n.w || 0), h: Math.round(n.h || 0),
          fanIn: cpl.fanIn,
          fanOut: cpl.fanOut,
        }
        if (n.shortTitle && n.shortTitle !== n.title) item.shortTitle = n.shortTitle
        if (n.domainTitle && n.domainTitle !== n.domain) item.domainTitle = n.domainTitle
        if (cpl.inCycle) item.inCycle = true
        if (cpl.cycleMembers?.length) item.cycleMembers = cpl.cycleMembers
        if (cpl.churnCommits) item.churnCommits = cpl.churnCommits
        if (n.description) item.description = n.description
        if (item.diffState !== 'context' && n.changeDetail && typeof n.changeDetail === 'object') {
          const cd = {}
          if (n.changeDetail.before) cd.before = n.changeDetail.before
          if (n.changeDetail.after) cd.after = n.changeDetail.after
          if (n.changeDetail.note) cd.note = n.changeDetail.note
          else if (Array.isArray(n.changeDetail.noteItems) && n.changeDetail.noteItems.length > 0) cd.note = n.changeDetail.noteItems.slice(0, 24).join('；')
          if (n.changeDetail.reason) cd.reason = n.changeDetail.reason
          if (n.changeDetail.replacementId) cd.replacementId = n.changeDetail.replacementId
          if (Array.isArray(n.changeDetail.scopeFiles) && n.changeDetail.scopeFiles.length > 0) cd.scopeFiles = n.changeDetail.scopeFiles.slice(0, 24)
          if (Array.isArray(n.changeDetail.criteriaRefs) && n.changeDetail.criteriaRefs.length > 0) cd.criteriaRefs = n.changeDetail.criteriaRefs.slice(0, 12)
          if (Object.keys(cd).length > 0) item.changeDetail = cd
        }
        if (item.diffState !== 'context' && n.impactReasons?.length) item.impactReasons = n.impactReasons.slice(0, 4)
        if (entries.length) item.entrypoints = entries
        if (mods.length) item.modules = mods
        if (tests.length) item.tests = tests
        if (vtools.length) item.verifyTools = vtools
        if (anchors.length) item.docAnchors = anchors
        return item
      }),
      edges: (tree.edges || []).map((e) => {
        const es = e.edgeState && e.edgeState !== 'context' ? e.edgeState : ''
        return mode === 'architecture-map' && LAZY_TAB_RENDER
          ? { fromId: e.fromId, toId: e.toId, ...(es ? { edgeState: es } : {}) }
          : { fromId: e.fromId, toId: e.toId, ...(es ? { edgeState: es } : {}), d: roundPathD(e.pathD) }
      }),
    },
    diagrams,
    walkthrough: (model?.walkthrough || []).map((w, idx) => (
      mode === 'architecture-map'
        ? { targetId: w.targetId || '' }
        : { index: idx, targetId: w.targetId || '', tab: w.tab || 'architecture', title: w.title || `步骤 ${idx + 1}`, detail: w.detail || '' }
    )),
  }
}
